```hcl
resource "aws_iam_role_policy" "example_resource" {
  name = "example-scoped-agentcore-policy"
  role = aws_iam_role.example_agentcore_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["bedrock-agentcore:InvokeAgentRuntime"] # Critical: enumerate actions instead of bedrock-agentcore:*
      Resource = "arn:aws:bedrock-agentcore:us-east-1:123456789012:runtime/example-runtime-id"
    }]
  })
}
```

